algorithms.pseudocode:
function E-PLANE(n, lines):
    total <- 0
    for k = 1..n:
        sign <- (-1)^(k+1)
        for each k-subset A of points:
            avoid <- #{ L in lines : L disjoint from A }
            p <- avoid / |lines|
            total <- total + sign / (1 - p)
    return total

function E-UNIF(n, q):
    total <- 0
    for k = 1..n:
        sign <- (-1)^(k+1)
        p <- C(n-k, q+1) / C(n, q+1)
        total <- total + sign * C(n, k) / (1 - p)
    return total
